('OLA14_LGAP_2014_01:LEY_GENERAL_ADMINISTRACION_PUBLICA:126','mayalex_normativos','10_LEYES_REGLAMENTOS','La presente Ley será publicada en el Diario Oficial "La Gaceta" y entrará en vigencia a partir del uno de enero de mil novecientos ochenta y siete.','126','Ley General de la Administración Pública de Honduras (Decreto No. 146-86)','{"norm_id":"HN:LEY_GENERAL_ADMINISTRACION_PUBLICA","instrumento_id":"LEY_GENERAL_ADMINISTRACION_PUBLICA","ingest_batch":"OLA14_LGAP_2014_01","ola":"OLA14","ordinal":131,"decreto":"146-86","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Corte Suprema de Justicia), «Ley General de la Administración Pública.pdf» (PDFMaker 2009, mod. 2012), con 38 notas al pie de los D.85-91, D.218-96, D.284-98, D.83-2004 y D.157-2008; arts. 2, 3, 4, 5, 6, 12, 13, 14, 15, 20, 22, 26, 27, 28, 29, 45, 50, 53, 85, 98, 99, 100, 101, 102, 113, 117, 124-C y 124-D según el D.266-2013 (La Gaceta 33,336), que además deroga los arts. 4A, 15A, 82, 104, 105, 124-A y 124-B.","pdf_sha256":"6d2e24a99413628e0bcfcadfacb94c196a3cdbacbd4ba3e3ae825ceaa8351a3a","article_sha256":"fb4971c56fadc273a41b7b5b13f892c3d3863a595b184b418f16ee27c2b981e9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_GENERAL_ADMINISTRACION_PUBLICA','126','fb4971c56fadc273a41b7b5b13f892c3d3863a595b184b418f16ee27c2b981e9','OLA14_LGAP_2014_01',now())
